        logs = []
        for f in os.listdir(self.log_dir):
            if f.endswith('.log'):
                logs.append(os.path.join(self.log_dir, f))
        return logs

    def count_404s(self) -> int:
        count = 0
        for log in self.get_log_files():
            count += self.count_404s_in_file(log)
        return count

    def count_404s_in_file(self, log_file: str) -> int:
        with open(log_file) as f:
            return sum(1 for line in f if '404' in line)

    def find_broken_urls(self) -> set[str]:
        urls = set()
        for log in self.get_log_files():
            urls |= self.find_broken_urls_in_file(log)
        return urls

    def find_broken_urls_in_file(self, log_file: str) -> set[str]:
        urls = set()
        with open(log_file) as f:
            for line in f:
                if '404' in line:
                    url = line.split(' ')[2]
                    urls.add(url)
        return urls

